// Validates protocol/requirements*.yaml and regenerates the files derived from
// it: docs/TRACEABILITY.md and src/conformance/generated/requirements.json.
//
//   node scripts/generate-traceability.mjs           write the generated files
//   node scripts/generate-traceability.mjs --check   fail if anything is invalid or stale
import { readFile, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import {
  profileClosure,
  profileDependencies,
  profiles,
  readRegistry,
  registryFiles,
  requirementsDigest,
  validateEvidence,
  validateRegistry,
  validateSourceAnchors,
} from './lib/requirements.mjs';

const packageRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const protocolRoot = resolve(packageRoot, '..', '..', 'protocol');
const traceabilityPath = resolve(packageRoot, 'docs', 'TRACEABILITY.md');
const requirementsJsonPath = resolve(packageRoot, 'src/conformance/generated/requirements.json');
const evidencePath = resolve(packageRoot, 'src/conformance/generated/evidence.json');
const checkOnly = process.argv.includes('--check');

const registries = await Promise.all(registryFiles.map((name) => readRegistry(protocolRoot, name)));
const [registry] = registries;
const allRequirements = registries.flatMap((item) => item.requirements);
const packageJson = JSON.parse(await readFile(resolve(packageRoot, 'package.json'), 'utf8'));
const evidence = JSON.parse(await readFile(evidencePath, 'utf8'));

const errors = [
  ...registries.flatMap((item, index) => validateRegistry(item, registryFiles[index])),
  ...validateRegistry({ version: 'all', requirements: allRequirements }, 'combined registries').filter(
    (message) => message.startsWith('Duplicate'),
  ),
  ...(await validateSourceAnchors(allRequirements, protocolRoot)),
];
if (errors.length > 0) throw new Error(`Requirement registry is invalid:\n- ${errors.join('\n- ')}`);

const evidenceErrors = validateEvidence(evidence, { registry, packageVersion: packageJson.version });
if (evidenceErrors.length > 0) {
  throw new Error(`${evidenceErrors.join('\n')}\nRun npm run refresh:evidence.`);
}

const passed = new Set(evidence.passedRequirementIds);
const bundledIds = new Set(registry.requirements.map((requirement) => requirement.id));
const evidenceCell = (requirement) => {
  if (!bundledIds.has(requirement.id)) return 'Not bundled';
  return passed.has(requirement.id) ? 'Verified' : '—';
};
const cell = (value) => String(value).replaceAll('|', '\\|').replaceAll('\n', ' ');
const code = (values) => values.map((value) => `\`${value}\``).join(', ') || '—';
const sourceLink = (source) => `[${source}](../../../protocol/${source})`;

const profileRows = profiles.map((profile) => {
  const closure = profileClosure(profile);
  const required = registry.requirements.filter(
    (requirement) =>
      closure.has(requirement.profile) &&
      (requirement.level === 'MUST' || requirement.level === 'MUST_NOT'),
  );
  const verified = required.filter((requirement) => passed.has(requirement.id)).length;
  const status = required.length > 0 && verified === required.length ? 'Complete' : 'Incomplete';
  return `| \`${profile}\` | ${code(profileDependencies[profile])} | ${required.length} | ${verified} | ${status} |`;
});

const traceability = [
  '# Protocol Traceability',
  '',
  '<!-- Generated by `npm run generate:traceability`. Do not edit by hand. -->',
  '',
  'Every requirement in `protocol/requirements.yaml` (COLP 0.1) and `protocol/requirements-0.2.yaml`',
  '(COLP 0.2 additions) is listed below with the package modules that implement it and the test IDs',
  'that verify it. A test carries an ID by including `[evidence:<test-id>]` in its `describe` or `it`',
  'name. "Verified" means every listed test passed in the last `npm run refresh:evidence` run.',
  'The bundled `evidence.json` covers COLP 0.1 only; the 0.2 additions run in the same test suite',
  'and are marked "Not bundled".',
  '',
  '## Profiles',
  '',
  'Required records count the COLP 0.1 MUST and MUST NOT requirements of the profile and all of its',
  'dependencies.',
  '',
  '| Profile | Depends on | Required records | Verified | Evidence |',
  '|---|---|---:|---:|---|',
  ...profileRows,
  '',
  '## Requirements',
  '',
  '| ID | Level | Profile | Requirement | Source | Implementation | Tests | Evidence |',
  '|---|---|---|---|---|---|---|---|',
  ...allRequirements.map(
    (requirement) =>
      `| \`${requirement.id}\` | ${requirement.level} | \`${requirement.profile}\` | ${cell(requirement.requirement)} | ${sourceLink(requirement.source)} | ${code(requirement.implementation)} | ${code(requirement.tests)} | ${evidenceCell(requirement)} |`,
  ),
  '',
].join('\n');

const requirementsJson = `${JSON.stringify(
  {
    protocolVersion: String(registry.version),
    packageVersion: packageJson.version,
    requirementsDigest: requirementsDigest(registry),
    requirements: registry.requirements,
  },
  null,
  2,
)}\n`;

if (checkOnly) {
  const [currentTraceability, currentJson] = await Promise.all([
    readFile(traceabilityPath, 'utf8'),
    readFile(requirementsJsonPath, 'utf8'),
  ]);
  if (currentTraceability !== traceability || currentJson !== requirementsJson) {
    throw new Error('Generated traceability files are stale. Run npm run generate:traceability.');
  }
} else {
  await Promise.all([
    writeFile(traceabilityPath, traceability, 'utf8'),
    writeFile(requirementsJsonPath, requirementsJson, 'utf8'),
  ]);
}

console.log(
  `${checkOnly ? 'Checked' : 'Generated'} traceability for ${allRequirements.length} requirements (${passed.size} verified).`,
);
